using System;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace RcsMap {
 public static class TerrainTests {
  static int count;
  static void Check(bool test,string name){if(!test)throw new Exception("terrain test failed: "+name);count++;}
  static void Throws(Action action,string name){bool caught=false;try{action();}catch{caught=true;}Check(caught,name);}
  static bool Error(MapDocument d,string text){return d.Validate(false).Any(s=>s.Contains(text));}
  public static void Run(string folder){Directory.CreateDirectory(folder);var flat=MapDocument.Demo();string flatJson=flat.Json();Check(!flatJson.Contains("Terrain")&&!flatJson.Contains("SurfaceId"),"legacy JSON has no extra fields");Check(MapDocument.Parse(flatJson).Json()==flatJson,"v3 roundtrip exact");Check(Exporter.Generate(flat).Count==6,"flat export retained");
   var d=TerrainGeometry.Demo();Check(d.Version==4,"terrain v4");Check(d.Validate().Count==0,"terrain demo valid: "+String.Join(" / ",d.Validate().ToArray()));string json=d.Json();Check(d.Clone().Json()==json,"v4 roundtrip");Check(TerrainGeometry.Height(d,d.Points[1])==75,"derived ramp height");d.Terrain.Surfaces[0].Z1=600;Check(TerrainGeometry.Height(d,d.Points[1])==90,"height updates with surface");d=TerrainGeometry.Demo();Throws(()=>Exporter.Generate(d),"no accidental slope C/H");Throws(()=>new PhasePreview(d),"no misleading flat dynamic preview");
   var ramp=d.Terrain.Surfaces[0];var deck=d.Terrain.Surfaces[1];TerrainLeg leg;string error;Check(TerrainGeometry.TryLeg(d,d.Points[0],d.Points[1],out leg,out error),"ground ramp link");Check(leg.Length>leg.Horizontal&&leg.Handoff>0&&leg.Handoff<1,"piecewise ground and slope distance");double expected=1000+Math.Sqrt(300*300+75*75);Check(Math.Abs(leg.Length-expected)<1e-6,"piecewise exact length");Check(TerrainGeometry.TryLeg(d,d.Points[2],d.Points[3],out leg,out error),"ramp deck link");
   var copy=d.Clone();copy.Terrain.Connections.Clear();Check(Error(copy,"未声明"),"explicit connection required");copy=d.Clone();copy.Terrain.Surfaces[1].Z0=550;Check(Error(copy,"接合边"),"height discontinuity rejected");copy=d.Clone();copy.Terrain.Surfaces[1].X+=50;Check(Error(copy,"接合边"),"gap rejected");copy=d.Clone();copy.Terrain.Surfaces[0].Depth=400;Check(Error(copy,"窄于"),"width limit");copy=d.Clone();copy.Terrain.MaxSlope=5;Check(Error(copy,"坡度"),"slope capability limit");copy=d.Clone();copy.Points[1].ArrivalActions.Add(new RouteAction{Kind=3,Value=1});Check(Error(copy,"停车动作"),"slope stop action rejected");copy=d.Clone();copy.Points[1].CorrectionMode=1;Check(Error(copy,"位置纠错"),"slope correction rejected");copy=d.Clone();copy.Points[0].SurfaceId=ramp.Id;Check(Error(copy,"所属表面")||Error(copy,"起点"),"invalid starting surface");
   var draft=d.Clone();draft.Terrain.Connections.Clear();Check(TerrainGeometry.CanOpenDraft(draft),"unfinished connection draft can reopen");Throws(()=>Exporter.Generate(draft),"draft cannot bypass export guard");draft.Points[0].X=Double.NaN;Check(!TerrainGeometry.CanOpenDraft(draft),"nonfinite draft not admitted to drawing");draft=d.Clone();draft.Terrain.Surfaces[0].Depth=0;Check(!TerrainGeometry.CanOpenDraft(draft),"zero-size draft not admitted");
   copy=d.Clone();copy.Terrain.Surfaces[0].Width=Double.NaN;Check(Error(copy,"参数无效"),"NaN rejected");copy=d.Clone();copy.Points[1].SurfaceId="deleted";Throws(()=>MapDocument.Parse(copy.Json()),"deleted surface reference rejected");copy=d.Clone();copy.Terrain.Connections.Add(new SurfaceConnection{A=deck.Id,B=ramp.Id});Throws(()=>copy.StructuralCheck(),"duplicate reverse link rejected");copy=d.Clone();copy.Version=3;Throws(()=>copy.StructuralCheck(),"terrain cannot masquerade v3");
   var bridge=new MapDocument{Version=4,Terrain=new TerrainMap()};var top=new TerrainSurface{Name="桥面",X=1500,Y=500,Width=2000,Depth=2500,Z0=800};bridge.Terrain.Surfaces.Add(top);bridge.Points.AddRange(new[]{new Waypoint(800,1500,0,100),new Waypoint(4500,1500,0,100)});Check(bridge.Validate().Count==0,"under bridge sufficient clearance");Check(!TerrainGeometry.HasRelief(bridge),"ground route under bridge remains flat");Check(Exporter.Generate(bridge).Count==6,"valid ground route export");bridge.Terrain.BodyHeight=800;Check(Error(bridge,"净空不足"),"vehicle height not radius used for clearance");bridge.Terrain.BodyHeight=300;bridge.Obstacles.Add(new Obstacle(2000,1200,500,500){SurfaceId=top.Id});Check(!Error(bridge,"障碍物安全包络"),"upper obstacle does not block lower lane");bridge.Obstacles[0].SurfaceId=null;Check(Error(bridge,"障碍物安全包络"),"same-floor obstacle blocks");bridge.Obstacles.Clear();bridge.Points[1].X=2000;bridge.Points[1].SurfaceId=top.Id;Check(!TerrainGeometry.TryLeg(bridge,bridge.Points[0],bridge.Points[1],out leg,out error),"XY overlap is not inter-floor travel");bridge.Terrain.Connections.Add(new SurfaceConnection{A=TerrainGeometry.Ground,B=top.Id});Check(Error(bridge,"接合边"),"fake vertical bridge connection rejected");
   var axis=new TerrainSurface{Kind=SurfaceKind.沿Y直坡道,X=0,Y=100,Width=1000,Depth=1000,Z0=300,Z1=0};Check(Math.Abs(axis.HeightAt(500,600)-150)<1e-6&&axis.Slope<0,"Y downhill height and signed slope");
   var down=TerrainGeometry.Demo();down.Points.Reverse();Check(down.Validate().Count==0,"reverse downhill route checks");
   var thick=new MapDocument{Version=4,Terrain=new TerrainMap()};var ceiling=new TerrainSurface{Name="厚桥面",X=1500,Y=500,Width=2000,Depth=2500,Z0=800,Thickness=500};thick.Terrain.Surfaces.Add(ceiling);thick.Points.AddRange(new[]{new Waypoint(800,1500,0,100),new Waypoint(4500,1500,0,100)});Check(Error(thick,"净空不足"),"bridge thickness counted");ceiling.Thickness=100;Check(!Error(thick,"净空不足"),"smaller actual thickness passes");
   var fast=d.Clone();fast.Points[1].Speed=250;Check(Error(fast,"限速"),"per-surface speed checked");var edge=d.Clone();edge.Points[1].Y=1950;Check(Error(edge,"侧边"),"ramp lateral vehicle envelope checked");
   var coincident=TerrainGeometry.Demo();coincident.Points[2].X=coincident.Points[1].X;coincident.Points[2].Y=coincident.Points[1].Y;Check(TerrainGeometry.TryLeg(coincident,coincident.Points[1],coincident.Points[2],out leg,out error)&&leg.Length==0,"same-surface stationary node geometry");
   var p=new Waypoint();p.ArrivalActions.Add(new RouteAction{Name="夹爪",Kind=0});p.ArrivalActions.Add(new RouteAction{Name="转头",Kind=2});p.DepartureActions.Add(new RouteAction{Name="升降",Kind=0});string id=p.ArrivalActions[1].Id;
   using(var dialog=new PhaseDialog(p,"")){Check(dialog.ArrivalBox.Visible==dialog.DepartureBox.Visible,"two action boxes exist together");Check(dialog.ArrivalBox.Text.Contains("到达航点后")&&dialog.DepartureBox.Text.Contains("离开航点前"),"explicit stages");dialog.ArrivalBox.List.SelectedIndex=1;dialog.ArrivalBox.MoveAction(-1);Check(p.ArrivalActions[0].Id==id&&p.DepartureActions.Count==1,"reorder isolated to arrival group");dialog.DepartureBox.List.SelectedIndex=0;dialog.DepartureBox.Remove();Check(p.DepartureActions.Count==0&&p.ArrivalActions.Count==2,"delete isolated to departure group");dialog.DepartureBox.Remove();Check(p.ArrivalActions.Count==2,"empty remove safe");}
   var before=d.Json();using(var dialog=new TerrainDialog(d)){dialog.Document.Terrain.Surfaces[0].Z1=999;Check(d.Json()==before,"terrain dialog is transactional clone");}
   var candidate=d.Clone();candidate.Points[0].ArrivalActions.Add(new RouteAction{Kind=0,Start="start();"});Check(d.Json()==before,"cancelled candidate leaves original unchanged");
   using(var dialog=new PhaseDialog(new Waypoint(),"")){dialog.Size=new System.Drawing.Size(1020,650);dialog.Opacity=0;dialog.ShowInTaskbar=false;dialog.Show();Application.DoEvents();Check(dialog.ArrivalBox.Visible&&dialog.DepartureBox.Visible,"both groups visible at minimum window");Check(dialog.ArrivalBox.Right<dialog.DepartureBox.Left&&dialog.ArrivalBox.Width>=300&&dialog.DepartureBox.Width>=300,"independent panes not overlapping");dialog.Close();}
   foreach(int view in new[]{0,1,2})using(var bitmap=new System.Drawing.Bitmap(900,620))using(var g=System.Drawing.Graphics.FromImage(bitmap))using(var canvas=new TerrainCanvas{Document=d,View=view}){canvas.Draw(g,new System.Drawing.Rectangle(0,0,900,620));bitmap.Save(Path.Combine(folder,"terrain-view"+view+".png"));Check(new FileInfo(Path.Combine(folder,"terrain-view"+view+".png")).Length>12000,"real view render "+view);}
   count+=TerrainDragTests.Run(folder);
   File.WriteAllText(Path.Combine(folder,"terrain-selftest.txt"),"PASS "+count+" terrain/action UI checks\n");Console.WriteLine("PASS "+count+" terrain/action UI checks");
  }
 }
}
